    id: "belarus-slutsk-belts-history-v2",
    type: "city",
    name: { de: "Historisches Sluzk", hu: "Történelmi Szluck", ro: "Slutskul Istoric", en: "Historic Slutsk" },
    coords: [27.5583, 53.0275],
